const provider = new BasicTracerProvider({
	spanProcessors: [new BatchSpanProcessor(new OTLPTraceExporter())],
});
const tracer = provider.getTracer("job");

const span = tracer.startSpan("nightly-job");
await runNightlyJob();
span.end();

process.exit(0);

